import { createRequire } from "node:module";

import type {
  MarbleClustersFile,
  MarbleDependenciesFile,
  MarbleTopicsFile,
  SlugMapFile,
  TaxonomyCluster,
  TaxonomyPrerequisite,
  TaxonomyTopic,
} from "./types.js";
import {
  MARBLE_DOMAIN_MAP,
  assertPrerequisiteStrength,
  marbleDomainKey,
  topicKindFromMarble,
} from "./mapping.js";

/**
 * The assembly layer: everything upstream-shaped stays inside this module.
 * It reads the vendored Marble JSON plus the frozen slug map
 * (data/homa-slug-map.json, generated by scripts/generate-slug-map.mts and
 * append-only) and derives the product-facing graph keyed entirely by Homa
 * ids. Nothing outside this file ever sees an `mt_` id except through a
 * topic's `refs` array.
 *
 * Centrality is recomputed here over the HOMA graph (normalized count of
 * transitive dependents, hard and soft edges alike): Marble's shipped
 * numbers describe their graph's shape, and ours diverges the moment
 * authored topics and edges land.
 */

const require = createRequire(import.meta.url);
const topicsFile = require("../data/topics.json") as MarbleTopicsFile;
const dependenciesFile = require("../data/dependencies.json") as MarbleDependenciesFile;
const clustersFile = require("../data/clusters.json") as MarbleClustersFile;
const slugMap = require("../data/homa-slug-map.json") as SlugMapFile;

export interface AssembledTaxonomy {
  topics: TaxonomyTopic[];
  prerequisites: TaxonomyPrerequisite[];
  clusters: TaxonomyCluster[];
  /** Marble "Subject > Domain" pairs missing from MARBLE_DOMAIN_MAP. */
  unmappedPairs: string[];
  /** Marble topic ids missing from the frozen slug map. */
  unmappedTopicIds: string[];
}

let assembled: AssembledTaxonomy | null = null;

const emDashPattern = /\s*\u2014\s*/g;

function sanitizeReferenceText(value: string): string {
  return value.replace(emDashPattern, ", ");
}

function sanitizeOptionalReferenceText(value: string): string | null {
  return value ? sanitizeReferenceText(value) : null;
}

function computeCentrality(
  topicIds: string[],
  prerequisites: TaxonomyPrerequisite[],
): Map<string, number> {
  // unlocks[p] = topics that list p as a prerequisite
  const unlocks = new Map<string, string[]>();
  for (const edge of prerequisites) {
    const list = unlocks.get(edge.prerequisiteId);
    if (list) list.push(edge.topicId);
    else unlocks.set(edge.prerequisiteId, [edge.topicId]);
  }

  const counts = new Map<string, number>();
  let max = 0;
  for (const id of topicIds) {
    const seen = new Set<string>();
    const queue = [id];
    while (queue.length > 0) {
      const current = queue.pop() as string;
      for (const next of unlocks.get(current) ?? []) {
        if (!seen.has(next)) {
          seen.add(next);
          queue.push(next);
        }
      }
    }
    counts.set(id, seen.size);
    if (seen.size > max) max = seen.size;
  }

  const centrality = new Map<string, number>();
  for (const [id, count] of counts) {
    centrality.set(id, max === 0 ? 0 : count / max);
  }
  return centrality;
}

export function assembleTaxonomy(): AssembledTaxonomy {
  if (assembled) return assembled;

  const unmappedPairs = new Set<string>();
  const unmappedTopicIds: string[] = [];
  const topics: TaxonomyTopic[] = [];
  const homaIdByMarbleId = new Map<string, string>();

  for (const marble of topicsFile.topics) {
    const key = marbleDomainKey(marble.subject, marble.domain);
    const target = MARBLE_DOMAIN_MAP[key];
    if (!target) {
      unmappedPairs.add(key);
      continue;
    }
    const homaId = slugMap[marble.id];
    if (!homaId) {
      unmappedTopicIds.push(marble.id);
      continue;
    }
    homaIdByMarbleId.set(marble.id, homaId);
    topics.push({
      id: homaId,
      subject: target.subject,
      domain: target.domainId,
      name: sanitizeReferenceText(marble.name),
      description: sanitizeReferenceText(marble.description),
      kind: topicKindFromMarble(marble.type),
      teachingWindowMonths: [marble.ageRangeStart * 12, marble.ageRangeEnd * 12],
      evidence: marble.evidence.map(sanitizeReferenceText),
      assessmentPrompt: sanitizeOptionalReferenceText(marble.assessmentPrompt),
      refs: [`marble:${marble.id}`, ...marble.standards],
      centrality: 0, // filled in below once edges are known
    });
  }

  const prerequisites: TaxonomyPrerequisite[] = [];
  for (const edge of dependenciesFile.dependencies) {
    const topicId = homaIdByMarbleId.get(edge.topicId);
    const prerequisiteId = homaIdByMarbleId.get(edge.prerequisiteId);
    // Edges touching an unmapped topic drop with it; the unmapped topic is
    // already reported above, and a dangling edge would be worse.
    if (!topicId || !prerequisiteId) continue;
    prerequisites.push({
      topicId,
      prerequisiteId,
      strength: assertPrerequisiteStrength(edge.strength),
      reason: sanitizeOptionalReferenceText(edge.reason),
    });
  }

  const centrality = computeCentrality(
    topics.map((topic) => topic.id),
    prerequisites,
  );
  for (const topic of topics) {
    topic.centrality = centrality.get(topic.id) ?? 0;
  }

  const clusters: TaxonomyCluster[] = [];
  for (const cluster of clustersFile.clusters) {
    const key = marbleDomainKey(cluster.subject, cluster.domain);
    const target = MARBLE_DOMAIN_MAP[key];
    if (!target) {
      unmappedPairs.add(key);
      continue;
    }
    clusters.push({
      subject: target.subject,
      domain: target.domainId,
      ageBandStartMonths: cluster.ageRangeStart * 12,
      summary: sanitizeReferenceText(cluster.summary),
    });
  }

  assembled = {
    topics,
    prerequisites,
    clusters,
    unmappedPairs: [...unmappedPairs].sort(),
    unmappedTopicIds,
  };
  return assembled;
}
